import pathlib
import json

# Use the 19 golden examples generated by Claude in gemma_core
GOLDEN_DIR = pathlib.Path(__file__).parent / "gemma_core" / "golden_examples"

SCENARIO_KEYWORDS = {
    "product_detail": ["商品详情", "详情页", "购买", "划线价"],
    "signup_form": ["报名", "表单"],
    "product_list": ["商品列表", "热销", "新品"],
    "booking_form": ["预约", "时段", "日期", "服务预约"],
    "store_intro": ["店铺", "营业时间", "评分", "人均"],
    "corporate_homepage": ["企业", "官网", "首页", "关于我们", "合作客户"],
    "course_detail": ["课程", "课时", "主讲", "大纲"],
    "news_list": ["新闻", "资讯列表", "文章列表", "头条"],
    "news_detail": ["新闻详情", "文章详情", "正文", "阅读数", "点赞"],
    "profile": ["个人中心", "我的", "会员", "头像", "设置"],
    "order_list": ["订单", "待付款", "待发货", "查看物流"],
    "coupon_claim": ["领券", "优惠券", "有效期", "满减"],
    "service_pricing": ["报价", "套餐", "年付", "月付", "专业版"],
    "job_posting": ["招聘", "岗位", "HR", "薪资", "福利"],
    "real_estate": ["房源", "二手房", "几室几厅", "面积", "地铁"],
    "restaurant_menu": ["点餐", "餐厅", "菜品", "套餐", "加减号"],
    "portfolio": ["作品集", "设计师", "案例", "流程"],
    "survey": ["问卷", "调查", "必填", "提交问卷"],
    "contact_us": ["联系我们", "留言", "地址", "联系方式"]
}

def get_golden_example(user_prompt: str) -> dict:
    """
    Returns the fallback golden example based on keyword matching in the prompt.
    Matches across 19 different scenarios to provide highly tailored context.
    Returns: {'wxml': '...', 'wxss': '...', 'js': '...'}
    """
    prompt_lower = user_prompt.lower()
    
    best_match = "product_detail" # default fallback
    max_hits = 0
    
    for scenario, keywords in SCENARIO_KEYWORDS.items():
        hits = sum(1 for kw in keywords if kw in prompt_lower)
        if hits > max_hits:
            max_hits = hits
            best_match = scenario
            
    return load_golden_from_folder(best_match)

def load_golden_from_folder(folder_name: str) -> dict:
    target_dir = GOLDEN_DIR / folder_name
    
    result = {}
    for ext in ['wxml', 'wxss', 'js']:
        file_path = target_dir / f"index.{ext}"
        if file_path.exists():
            with open(file_path, "r", encoding="utf-8") as f:
                result[ext] = f.read().strip()
        else:
            # fallback to txt just in case
            txt_path = target_dir / f"{ext}.txt"
            if txt_path.exists():
                with open(txt_path, "r", encoding="utf-8") as f:
                    result[ext] = f.read().strip()
            else:
                result[ext] = ""
            
    return result

def format_golden_as_three_blocks(folder_name: str) -> str:
    """Formats a golden example for few-shot prompting."""
    data = load_golden_from_folder(folder_name)
    blocks = [
        "===WXML===",
        data.get("wxml", ""),
        "===WXSS===",
        data.get("wxss", ""),
        "===JS===",
        data.get("js", "")
    ]
    return "\n".join(blocks)
